import{_ as e}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as n,d as i,a,o as l}from"./app-CGL0JtwU.js";const d={};function t(p,s){return l(),n("div",null,[s[0]||(s[0]=i(`<p>在嵌入式工程里，我们经常会接触两类静态库：</p><ul><li><strong>自己生产的库</strong>：把工程源码编译成 <code>.a</code>，交给第三方集成；</li><li><strong>别人交付的库</strong>：拿到供应商的 <code>.a</code>，再链接进自己的 ECU 工程。</li></ul><p>这两件事表面上都是“用静态库”，本质却处在构建链的两端。</p><p>本文基于一个 <strong>Infineon TC397 + TASKING TriCore v6.3r1 + AUTOSAR Classic</strong> 的真实工程取证，以工程自身生成的 <strong><code>libAdc.a</code></strong> 为 Producer 主案例，完整走一遍：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.c</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ TASKING cctc</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>relocatable .o</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ TASKING artc</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>libAdc.a</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ TASKING ltc</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>ELF</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>HEX</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>并在最后用第三方的 <code>libDrApp.a</code> 做 Consumer 侧对照。</p>`,6)),a(" more "),s[1]||(s[1]=i(`<h2 id="_1-先建立正确模型-compile、archive、link-是三件事" tabindex="-1"><a class="header-anchor" href="#_1-先建立正确模型-compile、archive、link-是三件事"><span>1. 先建立正确模型：Compile、Archive、Link 是三件事</span></a></h2><p>很多人第一次接触静态库时，会把“编译库”理解成一个步骤：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>源码 → libxxx.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>真实过程至少应该拆成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Source</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Compile</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Object</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Archive</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Static Library</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Link</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Executable Image</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在当前工程中，对应工具分别是：</p><table><thead><tr><th>阶段</th><th>TASKING 工具</th><th>主要职责</th></tr></thead><tbody><tr><td>Compile</td><td><code>cctc</code></td><td>C 源码编译，生成可重定位目标文件</td></tr><tr><td>Assemble</td><td><code>astc</code></td><td>TriCore 汇编器；显式 <code>.s</code> 规则直接使用</td></tr><tr><td>Archive</td><td><code>artc</code></td><td>把大量 <code>.o</code> 组织成静态归档 <code>.a</code></td></tr><tr><td>Link</td><td><code>ltc</code></td><td>抽取成员、解析符号、重定位、执行 LSL 放置并生成 ELF</td></tr></tbody></table><p>工程中的工具链版本为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>TASKING VX-toolset for TriCore v6.3r1</span></span>
<span class="line"><span>Target: tc39xb</span></span>
<span class="line"><span>Core:   tc1.6.2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>目标 MCU 为 TC397 / TC39x。</p><hr><h2 id="_2-stage-1-源码如何变成-o" tabindex="-1"><a class="header-anchor" href="#_2-stage-1-源码如何变成-o"><span>2. Stage 1：源码如何变成 <code>.o</code></span></a></h2><h3 id="_2-1-编译入口是-cctc" tabindex="-1"><a class="header-anchor" href="#_2-1-编译入口是-cctc"><span>2.1 编译入口是 <code>cctc</code></span></a></h3><p>工程 Makefile 中：</p><div class="language-makefile line-numbers-mode" data-highlighter="shiki" data-ext="makefile" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">CC</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> =</span><span style="--shiki-light:#383A42;--shiki-dark:#E5C07B;"> cctc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>并针对 TC39x 使用：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-Ctc39xb</span></span>
<span class="line"><span>--core=tc1.6.2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>例如一个真实编译单元：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Adc.c</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>最终生成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Adc.o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>从工具职责上，真实模型更准确地写成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Adc.c</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ cctc compiler driver</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ preprocessing</span></span>
<span class="line"><span>  ├─ C compilation / code generation</span></span>
<span class="line"><span>  └─ assembly</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Adc.o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也就是说，不应该理解成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.c → .o → astc → 又一个 .o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>astc</code> 是实际汇编工具，但对 C 文件，工程侧主要由 <code>cctc</code> 作为 driver 驱动完整流程；只有独立汇编源 <code>.s</code> 才在 MakeSupport 中看到显式 <code>astc</code> 规则。</p><h3 id="_2-2-编译阶段已经固定了很多东西" tabindex="-1"><a class="header-anchor" href="#_2-2-编译阶段已经固定了很多东西"><span>2.2 编译阶段已经固定了很多东西</span></a></h3><p>当前工程关键编译选项包括：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>--fp-model=2</span></span>
<span class="line"><span>--align=4</span></span>
<span class="line"><span>--default-near-size=0</span></span>
<span class="line"><span>--default-faraccess=call,xy</span></span>
<span class="line"><span>--use-address-registers=a10,a11</span></span>
<span class="line"><span>--no-clear</span></span>
<span class="line"><span>-O2</span></span>
<span class="line"><span>--iso=99</span></span>
<span class="line"><span>--language=-gcc,+volatile,+typeof</span></span>
<span class="line"><span>--exceptions</span></span>
<span class="line"><span>--c++-style-comments</span></span>
<span class="line"><span>--char-is-signed</span></span>
<span class="line"><span>--enum-size=int</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些参数很重要，因为一个静态库在变成 <code>.o</code> 时，就已经固定了一大批 ABI 和代码生成属性，例如：</p><ul><li>TriCore 指令集；</li><li>calling convention；</li><li>枚举表示；</li><li>对齐规则；</li><li>浮点模型；</li><li>符号命名；</li><li>section 名；</li><li>near/far 等地址模型相关属性。</li></ul><p>所以：</p><blockquote><p><strong>同样都是 TC397，并不意味着任意编译器、任意参数生成的库都天然兼容。</strong></p></blockquote><p>真正能否安全集成，还要看 ABI 和运行环境是否匹配。</p><hr><h2 id="_3-一个-o-里到底有什么" tabindex="-1"><a class="header-anchor" href="#_3-一个-o-里到底有什么"><span>3. 一个 <code>.o</code> 里到底有什么？</span></a></h2><p>从 <code>libAdc.a</code> 中取出真实成员，对 <code>Adc.o</code>、<code>CanServer.o</code> 等执行 TASKING <code>elfdump</code>，可以看到三个很关键的事实。</p><h3 id="_3-1-它已经有-defined-symbol" tabindex="-1"><a class="header-anchor" href="#_3-1-它已经有-defined-symbol"><span>3.1 它已经有 Defined Symbol</span></a></h3><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Adc_Init</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>已经是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>GLOBAL FUNC</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>也就是：</p><blockquote><p>这个 Object 已经知道“我实现了哪些函数”。</p></blockquote><h3 id="_3-2-它同时可以保留-undefined-symbol" tabindex="-1"><a class="header-anchor" href="#_3-2-它同时可以保留-undefined-symbol"><span>3.2 它同时可以保留 Undefined Symbol</span></a></h3><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Mcal_xxx</span></span>
<span class="line"><span>Rte_xxx</span></span>
<span class="line"><span>__d_xxx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>仍然可以处于：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>GLOBAL UND</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这并不代表编译失败。</p><p>Object 文件允许说：</p><blockquote><p>“我需要这个符号，但当前编译单元不负责实现它，留到以后链接时再找。”</p></blockquote><h3 id="_3-3-它还保留-relocation" tabindex="-1"><a class="header-anchor" href="#_3-3-它还保留-relocation"><span>3.3 它还保留 Relocation</span></a></h3><p><code>.o</code> 中存在 <code>.rela.*</code> 等 relocation 信息。</p><p>这说明此时：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>函数在哪里？</span></span>
<span class="line"><span>全局变量在哪里？</span></span>
<span class="line"><span>外部符号最终地址是多少？</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>都还没有最终决定。</p><p>因此可以把 <code>.o</code> 理解成：</p><blockquote><p><strong>已经生成机器代码，但仍然可以搬家、仍然等待外部符号解析的可重定位模块。</strong></p></blockquote><hr><h2 id="_4-section-名在什么时候产生" tabindex="-1"><a class="header-anchor" href="#_4-section-名在什么时候产生"><span>4. Section 名在什么时候产生？</span></a></h2><p>这是嵌入式库与普通 PC Library 很不一样的地方。</p><p>在实际 Object 中可以看到类似：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.text.MSR_CODE</span></span>
<span class="line"><span>.rodata.MSR_PBCONST</span></span>
<span class="line"><span>.bss.MSR_VAR_CLEARED</span></span>
<span class="line"><span>.bss.bss_lmu1_core0</span></span>
<span class="line"><span>.bss.OS_CORE0_VAR_CLEARED</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些名字并不是 Linker 最后临时发明出来的。</p><p>工程通过 MemMap / <code>#pragma section</code> 等机制，在<strong>编译阶段</strong>就把函数和变量归入特定 section。</p><p>流程可以理解为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>变量 / 函数</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ MemMap / pragma</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Section Name</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ 编译进 .o</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>.text.xxx / .data.xxx / .bss.xxx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真正到 Link 阶段，LSL 做的是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Section Name</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Memory Region</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>最终地址</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也就是说：</p><blockquote><p><strong>Compiler 决定“属于哪一类 Section”，Linker 决定“这个 Section 最后放到哪”。</strong></p></blockquote><hr><h2 id="_5-stage-2-为什么工程要生成-libadc-a" tabindex="-1"><a class="header-anchor" href="#_5-stage-2-为什么工程要生成-libadc-a"><span>5. Stage 2：为什么工程要生成 <code>libAdc.a</code></span></a></h2><p>当前工程存在一个很关键的构建开关：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>RELEASE_FLAG</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>取证发现，Release 模式不是简单地“再生成一个库文件”，而是存在 <strong>Source Mode → Library Mode</strong> 的切换机制。</p><p>在相关 Global Makefile 中：</p><ul><li>某些对象 / library path / include dir 会被重新整理；</li><li>Release 路径下会生成 <code>libAdc.a</code>；</li><li>随后最终工程通过 <code>-lAdc</code> 再消费这个库。</li></ul><p>这形成了一条很有价值的自验证链：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>工程源码</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>编译</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Object</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>libAdc.a</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>同一工程 Release Link</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此 <code>libAdc.a</code> 并不是一个抽象概念，它正是工程提供给外部集成者时可以使用的二进制交付形态。</p><hr><h2 id="_6-719-个-object-如何变成一个-libadc-a" tabindex="-1"><a class="header-anchor" href="#_6-719-个-object-如何变成一个-libadc-a"><span>6. 719 个 Object 如何变成一个 <code>libAdc.a</code></span></a></h2><h3 id="_6-1-先生成成员列表" tabindex="-1"><a class="header-anchor" href="#_6-1-先生成成员列表"><span>6.1 先生成成员列表</span></a></h3><p>取证得到：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>libAdc_objs.rsp</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>最终参与归档的 Object 数量为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>719</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>随后形成供 Archiver 使用的 response file。</p><h3 id="_6-2-真正的归档命令" tabindex="-1"><a class="header-anchor" href="#_6-2-真正的归档命令"><span>6.2 真正的归档命令</span></a></h3><p>工程确认：</p><div class="language-makefile line-numbers-mode" data-highlighter="shiki" data-ext="makefile" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">AR</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> =</span><span style="--shiki-light:#383A42;--shiki-dark:#E5C07B;"> artc</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">ARFLAGS</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> =</span><span style="--shiki-light:#383A42;--shiki-dark:#E5C07B;"> -cr</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>实际规则等价于：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>删除旧 libAdc.a</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>artc -cr libAdc.a -f libAdc.rsp</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里“先删旧文件”很重要。</p><p>它避免旧 archive member 因增量更新而意外残留，使本次 <code>libAdc.a</code> 的成员集合完全由新的 response file 决定。</p><p>最终生成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>libAdc.a</span></span>
<span class="line"><span>size ≈ 134,003,004 bytes</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_7-a-本质上是什么" tabindex="-1"><a class="header-anchor" href="#_7-a-本质上是什么"><span>7. <code>.a</code> 本质上是什么？</span></a></h2><p>对 <code>libAdc.a</code> 检查后：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>magic = !&lt;arch&gt;</span></span>
<span class="line"><span>members = 719</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>使用：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">artc</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -t</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> libAdc.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可以直接列出归档成员，其中包含真实的：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Adc.o</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>因此一个静态库可以非常直观地理解为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>libAdc.a</span></span>
<span class="line"><span>├── Object_A.o</span></span>
<span class="line"><span>├── Object_B.o</span></span>
<span class="line"><span>├── Adc.o</span></span>
<span class="line"><span>├── CanServer.o</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>└── Archive Symbol Index</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它不是已经完成最终地址分配的“半个 ELF”。</p><p>更准确地说，它是：</p><blockquote><p><strong>一组 relocatable Object + 用于快速检索符号的 Archive Index。</strong></p></blockquote><hr><h2 id="_8-archive-不负责解决符号" tabindex="-1"><a class="header-anchor" href="#_8-archive-不负责解决符号"><span>8. Archive 不负责解决符号</span></a></h2><p>这是整个静态库机制里最重要的概念之一。</p><p><code>libAdc.a</code> 中聚合得到的 Undefined Symbol 数量为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>17146</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>进一步分析：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>16707</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可以在库内部其它 Object 中找到定义。</p><p>剩余真正需要最终 Consumer 提供的外部符号约：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>439</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>包括：</p><ul><li>LSL 边界符号；</li><li>TASKING 浮点运行时中的 <code>__d_*</code>；</li><li>TASKING runtime 中的 <code>__ll_*</code>；</li><li>以及其它平台侧依赖。</li></ul><p>这说明：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>artc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在创建 <code>libAdc.a</code> 时并不会要求：</p><blockquote><p>“所有 Undefined Symbol 必须全部解决。”</p></blockquote><p>它只负责：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.o</span></span>
<span class="line"><span> +</span></span>
<span class="line"><span>.o</span></span>
<span class="line"><span> +</span></span>
<span class="line"><span>.o</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Archive</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真正的 Symbol Resolution 要留给最终 Link。</p><hr><h2 id="_9-archive-阶段到底做了什么、没做什么" tabindex="-1"><a class="header-anchor" href="#_9-archive-阶段到底做了什么、没做什么"><span>9. Archive 阶段到底做了什么、没做什么？</span></a></h2><p>可以用一张表概括：</p><table><thead><tr><th>行为</th><th style="text-align:right;">Compile</th><th style="text-align:right;">Archive</th><th style="text-align:right;">Link</th></tr></thead><tbody><tr><td>C → Machine Code</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td></tr><tr><td>生成 Section</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td></tr><tr><td>生成 Symbol</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td></tr><tr><td>保存 Relocation</td><td style="text-align:right;">✅</td><td style="text-align:right;">保留</td><td style="text-align:right;">处理</td></tr><tr><td>打包多个 Object</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td></tr><tr><td>建立 Archive Index</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td><td style="text-align:right;">使用</td></tr><tr><td>解析外部符号</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr><tr><td>决定最终地址</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr><tr><td>执行 LSL Placement</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr><tr><td>生成 ELF</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr></tbody></table><p>所以：</p><blockquote><p><strong>Archive 基本不改变 Object 的二进制语义，它主要负责组织与索引。</strong></p></blockquote><hr><h2 id="_10-为什么-134-mb-的-a-不代表-134-mb-flash" tabindex="-1"><a class="header-anchor" href="#_10-为什么-134-mb-的-a-不代表-134-mb-flash"><span>10. 为什么 134 MB 的 <code>.a</code> 不代表 134 MB Flash？</span></a></h2><p>这是工程中非常容易误判的问题。</p><p><code>libAdc.a</code> 包含：</p><ul><li>真正会进入 ECU 的代码/常量/数据；</li><li>Symbol Table；</li><li>String Table；</li><li>Relocation；</li><li>TASKING metadata；</li><li>DWARF Debug Information；</li><li>Archive Index；</li><li>Object 元数据。</li></ul><p>因此：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>libAdc.a file size</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>Flash usage</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>甚至：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>ELF file size</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>Flash usage</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终 Flash / RAM 占用应该看：</p><ul><li>Link Map；</li><li>ALLOC Section；</li><li>Memory Region；</li><li>最终 HEX / binary layout。</li></ul><p>当前 <code>libAdc.a</code> 没有 strip，成员还包含 DWARF 信息，因此 archive 本身很大是正常的。</p><p>这也带来另一个 Release Hygiene 问题：</p><blockquote><p>如果对外交付二进制库，需要关注 Debug Info、绝对源码路径、member timestamp 等元信息是否应该保留。</p></blockquote><hr><h2 id="_11-stage-3-consumer-怎么使用-libadc-a" tabindex="-1"><a class="header-anchor" href="#_11-stage-3-consumer-怎么使用-libadc-a"><span>11. Stage 3：Consumer 怎么使用 <code>libAdc.a</code></span></a></h2><p>Release 模式下，工程最终会：</p><div class="language-makefile line-numbers-mode" data-highlighter="shiki" data-ext="makefile" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">SYSLIBS</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> +=</span><span style="--shiki-light:#383A42;--shiki-dark:#E5C07B;"> -lAdc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>同时当前目录：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-L./</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>位于 library search path。</p><p>于是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-lAdc</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>搜索 libAdc.a</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>交给 ltc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里必须区分：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-L</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>和：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-l</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>的职责：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-Lxxx    = 去哪里找</span></span>
<span class="line"><span>-lAdc    = 要找哪个库</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_12-linker-并不会把整个-libadc-a-都塞进-elf" tabindex="-1"><a class="header-anchor" href="#_12-linker-并不会把整个-libadc-a-都塞进-elf"><span>12. Linker 并不会把整个 <code>libAdc.a</code> 都塞进 ELF</span></a></h2><p>静态库最大的价值之一就在这里。</p><p>假设 archive 中有：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>719 个 Object</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Linker 不需要把 719 个全部放入镜像。</p><p>它从当前 unresolved symbol 开始：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>某个 Object 需要 Foo()</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Archive Symbol Index</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>找到 Foo 所在 Member</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>抽取 Member</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>该 Member 又产生新的 Undefined Symbol</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>继续解析</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实际工程的 Map 已经能在其它静态库上看到类似信息：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Member[libSocManager.a|timer_soft_timer.o]</span></span>
<span class="line"><span>Symbol[...]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这证明 TASKING Map 能记录：</p><blockquote><p><strong>哪个符号触发了哪个 Archive Member 被拉入最终镜像。</strong></p></blockquote><p>当前缺少一次 <code>RELEASE_FLAG=1</code> 的完整 Map，因此：</p><blockquote><p><code>libAdc.a</code> 在 Release ON 时具体抽取了哪些成员、每个成员最终地址是多少，目前仍然是 Unknown。</p></blockquote><p>这也是现阶段最值得继续补的一项证据。</p><hr><h2 id="_13-symbol-resolution-剩下的-439-个符号怎么办" tabindex="-1"><a class="header-anchor" href="#_13-symbol-resolution-剩下的-439-个符号怎么办"><span>13. Symbol Resolution：剩下的 439 个符号怎么办？</span></a></h2><p>当 Linker 把需要的 <code>libAdc.a</code> 成员抽出来以后，成员内部仍可能引用外部符号。</p><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>__d_xxx</span></span>
<span class="line"><span>__ll_xxx</span></span>
<span class="line"><span>LSL boundary symbol</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终工程还需要：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-lfp</span></span>
<span class="line"><span>-lrt</span></span>
<span class="line"><span>其它平台对象</span></span>
<span class="line"><span>LSL 定义</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>继续完成解析。</p><p>于是最终链接的核心问题不再是：</p><blockquote><p>“Library 文件存在吗？”</p></blockquote><p>而是：</p><blockquote><p>“所有真正被抽取进来的 Object，其 Undefined Symbol 能否在整个链接输入集合中被满足？”</p></blockquote><p>这才是判断一个静态库能不能成功集成的关键。</p><p>对于当前 TASKING <code>ltc</code>，取证表明其 library 解析行为不能简单套用 GNU ld 的“一次从左往右扫描”经验；当前配置会对库进行多次扫描。因此讨论 library order 时，应以具体 TASKING Linker 行为为准，而不是直接套 GNU 工具链结论。</p><hr><h2 id="_14-lsl-在这个阶段才真正决定地址" tabindex="-1"><a class="header-anchor" href="#_14-lsl-在这个阶段才真正决定地址"><span>14. LSL 在这个阶段才真正决定地址</span></a></h2><p>编译阶段已经产生：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.bss.bss_lmu1_core0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>但它还不知道最后实际地址。</p><p>工程 <code>vLinkGen_Template.lsl</code> 中存在对应规则，例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>select &quot;[.]bss.bss_lmu1_core0&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>然后将其映射到相应 Memory Region，并产生相关 Linker boundary symbol。</p><p>完整过程：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Source Variable</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>MemMap / pragma</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>.bss.bss_lmu1_core0</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Object</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>libAdc.a</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ltc</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>LSL select</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>LMU / DSPR / PFlash ...</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Final Address</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这正好说明：</p><blockquote><p><strong>Section Name 是 Compile-time Contract，Memory Address 是 Link-time Decision。</strong></p></blockquote><hr><h2 id="_15-startup-也是静态库契约的一部分" tabindex="-1"><a class="header-anchor" href="#_15-startup-也是静态库契约的一部分"><span>15. Startup 也是静态库契约的一部分</span></a></h2><p>当前工程存在：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>--no-clear</span></span>
<span class="line"><span>--user-provided-initialization-code</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>因此变量初始化并不是一句：</p><blockquote><p>“Linker 把 <code>.data/.bss</code> 放进去就结束了。”</p></blockquote><p>还涉及：</p><ul><li>initialized data 的 load / run address；</li><li>Copy Table；</li><li>zero initialization；</li><li>startup code；</li><li>Linker 生成的边界符号。</li></ul><p>所以一个对外交付的嵌入式静态库，如果包含特殊：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.data.xxx</span></span>
<span class="line"><span>.bss.xxx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>就不能只告诉第三方：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>-lAdc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>还应该明确：</p><blockquote><p>Consumer 的 LSL 和 Startup 是否能够正确处理这些 Section。</p></blockquote><p>这也是嵌入式静态库与普通桌面软件静态库集成的核心差异之一。</p><hr><h2 id="_16-stage-4-最后生成-elf-hex" tabindex="-1"><a class="header-anchor" href="#_16-stage-4-最后生成-elf-hex"><span>16. Stage 4：最后生成 ELF / HEX</span></a></h2><p>Linker 完成：</p><ol><li>Archive Member Extraction</li><li>Symbol Resolution</li><li>Relocation</li><li>Section Placement</li><li>Address Assignment</li></ol><p>之后生成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>TestSuit.elf</span></span>
<span class="line"><span>TestSuit.map</span></span>
<span class="line"><span>TestSuit.hex</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>现有取证中的 <code>TestSuit.elf</code> 约：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>69,969,736 bytes</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>但这个现有产物属于：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>RELEASE_FLAG = OFF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>也就是：</p><blockquote><p>工程 Object 直接进入 ELF，并没有通过 <code>libAdc.a → -lAdc</code> 的 Release 自消费路径。</p></blockquote><p>因此目前能确认：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Source → Object → ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以及：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Source → Object → libAdc.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>都已经跑通。</p><p>而：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>libAdc.a → 按需抽取 → Final ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这一段机制已经确认，但 <code>libAdc.a</code> 自身在 Release ON 下的逐成员地址证据仍待一次安全构建闭环。</p><hr><h2 id="_17-一张图总结完整生命周期" tabindex="-1"><a class="header-anchor" href="#_17-一张图总结完整生命周期"><span>17. 一张图总结完整生命周期</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>┌──────────────────── Producer ────────────────────┐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ADC Source (.c)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ cctc</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Relocatable Objects (.o)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │  section / symbol / relocation 已存在</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>719 Objects</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ artc -cr libAdc.a -f libAdc.rsp</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>libAdc.a</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ !&lt;arch&gt;</span></span>
<span class="line"><span>      ├─ Object Members</span></span>
<span class="line"><span>      └─ Archive Symbol Index</span></span>
<span class="line"><span></span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       │ Delivery / Release</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>┌──────────────────── Consumer ────────────────────┐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-L...</span></span>
<span class="line"><span>-lAdc</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>TASKING ltc</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ├─ Archive Member Extraction</span></span>
<span class="line"><span>      ├─ Symbol Resolution</span></span>
<span class="line"><span>      ├─ Runtime Libraries</span></span>
<span class="line"><span>      ├─ Relocation</span></span>
<span class="line"><span>      └─ LSL Placement</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>TestSuit.elf</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>HEX / ECU</span></span>
<span class="line"><span></span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_18-反过来看第三方库-libdrapp-a" tabindex="-1"><a class="header-anchor" href="#_18-反过来看第三方库-libdrapp-a"><span>18. 反过来看第三方库 <code>libDrApp.a</code></span></a></h2><p>前面的 <code>libAdc.a</code> 是：</p><blockquote><p><strong>当前工程作为 Producer。</strong></p></blockquote><p>而第三方交付的 <code>libDrApp.a</code> 正好提供了另一侧案例：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>第三方源码</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>供应商编译</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>libDrApp.a</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>当前工程</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>-lDrApp</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ltc</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当前工程通过：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>DEEPROUTE_SWC_FLAG=1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>同时完成：</p><ul><li>切换对应 SWC Wrapper；</li><li>增加 library search path；</li><li>增加 <code>-lDrApp</code>；</li><li>增加配套 <code>-lc_tc397</code>。</li></ul><p>因此两个案例刚好形成镜像：</p><table><thead><tr><th>视角</th><th>案例</th></tr></thead><tbody><tr><td>我怎么把自己的源码做成库</td><td><code>libAdc.a</code></td></tr><tr><td>我怎么把别人的库接入工程</td><td><code>libDrApp.a</code></td></tr></tbody></table><p>理解了前者，后者的很多问题就自然清楚了。</p><hr><h2 id="_19-producer-和-consumer-真正需要对齐什么" tabindex="-1"><a class="header-anchor" href="#_19-producer-和-consumer-真正需要对齐什么"><span>19. Producer 和 Consumer 真正需要对齐什么？</span></a></h2><p>一个静态库能够被另一个嵌入式工程正确使用，至少需要检查：</p><h3 id="编译-abi" tabindex="-1"><a class="header-anchor" href="#编译-abi"><span>编译 / ABI</span></a></h3><ul><li>CPU Architecture</li><li>TriCore ISA</li><li>Compiler ABI</li><li>Calling Convention</li><li>Enum Model</li><li>Alignment</li><li>Floating Point Model</li><li>C / C++ ABI</li><li>Address Model</li></ul><h3 id="link" tabindex="-1"><a class="header-anchor" href="#link"><span>Link</span></a></h3><ul><li>Public Header</li><li>Library Search Path</li><li>Library Name</li><li>Undefined Symbol Provider</li><li>Runtime Library</li><li>Library Dependency</li><li>TASKING Linker 行为</li></ul><h3 id="memory" tabindex="-1"><a class="header-anchor" href="#memory"><span>Memory</span></a></h3><ul><li>Custom Section</li><li>LSL Select</li><li>PFlash / LMU / DSPR 等 Region</li><li>Copy / Clear</li><li>Startup</li></ul><h3 id="runtime" tabindex="-1"><a class="header-anchor" href="#runtime"><span>Runtime</span></a></h3><ul><li>Init 顺序</li><li>API 生命周期</li><li>Task / Core</li><li>Stack</li><li>Heap</li><li>RTE / BSW / MCAL 依赖</li></ul><p>所以：</p><blockquote><p><strong>“给一个 <code>.a</code> 文件”并不等于完成嵌入式 Library Delivery。</strong></p></blockquote><p>真正的交付对象应该是一套完整的二进制接口契约。</p><hr><h2 id="_20-最容易混淆的几个概念" tabindex="-1"><a class="header-anchor" href="#_20-最容易混淆的几个概念"><span>20. 最容易混淆的几个概念</span></a></h2><h3 id="_20-1-o-不是最终机器镜像" tabindex="-1"><a class="header-anchor" href="#_20-1-o-不是最终机器镜像"><span>20.1 <code>.o</code> 不是最终机器镜像</span></a></h3><p>它已经有机器码，但：</p><ul><li>可以有 Undefined Symbol；</li><li>可以有 Relocation；</li><li>没有最终运行地址。</li></ul><h3 id="_20-2-a-不是把所有依赖都链接好了" tabindex="-1"><a class="header-anchor" href="#_20-2-a-不是把所有依赖都链接好了"><span>20.2 <code>.a</code> 不是把所有依赖都链接好了</span></a></h3><p>它主要是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Object 集合 + Symbol Index</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因此完全可以保留外部依赖。</p><h3 id="_20-3-静态库文件大-不代表-flash-占用大" tabindex="-1"><a class="header-anchor" href="#_20-3-静态库文件大-不代表-flash-占用大"><span>20.3 静态库文件大，不代表 Flash 占用大</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>archive size</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>linked code size</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>Flash usage</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_20-4-section-和-address-不是一回事" tabindex="-1"><a class="header-anchor" href="#_20-4-section-和-address-不是一回事"><span>20.4 Section 和 Address 不是一回事</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>Compiler → Section Name</span></span>
<span class="line"><span>Linker   → Final Address</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_20-5-能找到-library-不代表集成成功" tabindex="-1"><a class="header-anchor" href="#_20-5-能找到-library-不代表集成成功"><span>20.5 能找到 Library，不代表集成成功</span></a></h3><p>真正需要闭环：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>找到库</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>抽取成员</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>符号全部解析</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Section 正确放置</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Startup 正确初始化</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Runtime 正确执行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_21-当前证据已经确认什么-什么还没有确认" tabindex="-1"><a class="header-anchor" href="#_21-当前证据已经确认什么-什么还没有确认"><span>21. 当前证据已经确认什么，什么还没有确认？</span></a></h2><table><thead><tr><th>项目</th><th>状态</th></tr></thead><tbody><tr><td>TC397 / TASKING v6.3r1</td><td>Confirmed</td></tr><tr><td><code>.c → .o</code> 编译规则</td><td>Confirmed</td></tr><tr><td>ABI 关键编译参数</td><td>Confirmed</td></tr><tr><td>Section 编译期产生</td><td>Confirmed</td></tr><tr><td><code>libAdc.a</code> 使用 <code>artc</code></td><td>Confirmed</td></tr><tr><td>719 个 Archive Member</td><td>Confirmed</td></tr><tr><td><code>!&lt;arch&gt;</code> 格式</td><td>Confirmed</td></tr><tr><td>Archive 保留 relocation / undefined symbol</td><td>Confirmed</td></tr><tr><td>Release 模式使用 <code>-lAdc</code></td><td>Confirmed</td></tr><tr><td>Linker 按需抽取机制</td><td>Confirmed</td></tr><tr><td>LSL 决定最终 Region / Address</td><td>Confirmed</td></tr><tr><td>Release ON 时 <code>libAdc.a</code> 实际抽取哪些成员</td><td><strong>Unknown</strong></td></tr><tr><td>Release ON 时成员最终地址</td><td><strong>Unknown</strong></td></tr><tr><td>最大 Stack</td><td><strong>Unknown</strong></td></tr><tr><td>完整逐条 <code>-I</code> 编译命令</td><td><strong>Unknown</strong></td></tr><tr><td>正式第三方交付包完整清单</td><td><strong>Unknown</strong></td></tr></tbody></table><p>保留 Unknown 很重要。</p><p>工程分析最危险的不是“不知道”，而是：</p><blockquote><p><strong>把“机制上应该如此”写成“当前工程已经证明如此”。</strong></p></blockquote><hr><h2 id="_22-最终结论" tabindex="-1"><a class="header-anchor" href="#_22-最终结论"><span>22. 最终结论</span></a></h2><p>从这个 TC397 + TASKING 工程可以非常清楚地看到，静态库生命周期不是一句：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>编译成 .a 然后链接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>而是一条严格分层的流水线：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code><span class="line"><span>.c</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ 编译：固定 ISA / ABI / Symbol / Section</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.o</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ 归档：组织 Object + 建立 Symbol Index</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.a</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ 链接：按需抽取 + Symbol Resolution + Relocation</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>LSL</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ 决定 Memory Region / Final Address</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>ELF</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>HEX / ECU Runtime</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中最值得记住的是三句话：</p><blockquote><p><strong>第一，<code>.o</code> 可以保留 Undefined Symbol，因为最终解析发生在 Link。</strong></p></blockquote><blockquote><p><strong>第二，<code>.a</code> 本质上是一组可重定位 Object 的归档，而不是已经完成链接的程序。</strong></p></blockquote><blockquote><p><strong>第三，嵌入式库是否真正可用，不只取决于 API，还取决于 ABI、Runtime、Section、LSL、Startup 和最终执行环境。</strong></p></blockquote><p>一旦把 <strong>Compile → Archive → Link</strong> 三个阶段真正分开，很多常见问题——为什么 <code>-lxxx</code> 会报错、为什么 Library 很大但 Flash 增量很小、为什么同样 TC397 的库仍可能不能用、为什么还需要修改 LSL——都会变得非常直观。</p>`,305))])}const h=e(d,[["render",t]]),o=JSON.parse('{"path":"/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html","title":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程","lang":"zh-CN","frontmatter":{"title":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程","icon":"code","date":"2026-09-30T00:00:00.000Z","category":["Autosar"],"tag":["TC397","TASKING","静态库","Linker","AUTOSAR"],"isOriginal":true,"article":true,"timeline":true,"description":"在嵌入式工程里，我们经常会接触两类静态库： 自己生产的库：把工程源码编译成 .a，交给第三方集成； 别人交付的库：拿到供应商的 .a，再链接进自己的 ECU 工程。 这两件事表面上都是“用静态库”，本质却处在构建链的两端。 本文基于一个 Infineon TC397 + TASKING TriCore v6.3r1 + AUTOSAR Classic ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-09-30T00:00:00.000Z\\",\\"dateModified\\":\\"2026-09-30T02:08:51.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Bin\\",\\"url\\":\\"https://binkyle.github.io/\\"}]}"],["meta",{"property":"og:url","content":"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html"}],["meta",{"property":"og:site_name","content":"Bin"}],["meta",{"property":"og:title","content":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程"}],["meta",{"property":"og:description","content":"在嵌入式工程里，我们经常会接触两类静态库： 自己生产的库：把工程源码编译成 .a，交给第三方集成； 别人交付的库：拿到供应商的 .a，再链接进自己的 ECU 工程。 这两件事表面上都是“用静态库”，本质却处在构建链的两端。 本文基于一个 Infineon TC397 + TASKING TriCore v6.3r1 + AUTOSAR Classic ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-30T02:08:51.000Z"}],["meta",{"property":"article:tag","content":"AUTOSAR"}],["meta",{"property":"article:tag","content":"Linker"}],["meta",{"property":"article:tag","content":"静态库"}],["meta",{"property":"article:tag","content":"TASKING"}],["meta",{"property":"article:tag","content":"TC397"}],["meta",{"property":"article:published_time","content":"2026-09-30T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-30T02:08:51.000Z"}]]},"git":{"createdTime":1790734131000,"updatedTime":1790734131000,"contributors":[{"name":"binkyle","username":"binkyle","email":"96855579+binkyle@users.noreply.github.com","commits":1,"url":"https://github.com/binkyle"}]},"readingTime":{"minutes":12.89,"words":3868},"filePathRelative":"blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.md","excerpt":"<p>在嵌入式工程里，我们经常会接触两类静态库：</p>\\n<ul>\\n<li><strong>自己生产的库</strong>：把工程源码编译成 <code>.a</code>，交给第三方集成；</li>\\n<li><strong>别人交付的库</strong>：拿到供应商的 <code>.a</code>，再链接进自己的 ECU 工程。</li>\\n</ul>\\n<p>这两件事表面上都是“用静态库”，本质却处在构建链的两端。</p>\\n<p>本文基于一个 <strong>Infineon TC397 + TASKING TriCore v6.3r1 + AUTOSAR Classic</strong> 的真实工程取证，以工程自身生成的 <strong><code>libAdc.a</code></strong> 为 Producer 主案例，完整走一遍：</p>\\n<div class=\\"language-text line-numbers-mode\\" data-highlighter=\\"shiki\\" data-ext=\\"text\\" style=\\"--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34\\"><pre class=\\"shiki shiki-themes one-light one-dark-pro vp-code\\"><code><span class=\\"line\\"><span>.c</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ TASKING cctc</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>relocatable .o</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ TASKING artc</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>libAdc.a</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ TASKING ltc</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>ELF</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>HEX</span></span></code></pre>\\n<div class=\\"line-numbers\\" aria-hidden=\\"true\\" style=\\"counter-reset:line-number 0\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div></div></div><p>并在最后用第三方的 <code>libDrApp.a</code> 做 Consumer 侧对照。</p>\\n","autoDesc":true}');export{h as comp,o as data};
